import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Design specs
  const CARD_WIDTH = 1.6;
  const CARD_HEIGHT = 1.0;
  const CARD_PITCH = 1.85;
  const BEVEL_WIDTH = 0.025;
  const STRIP_ROTATION_Y = -18 * Math.PI / 180;

  const captions = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];

  // Build 5 cards
  const cardsArray = [];
  for (let i = 0; i < 5; i++) {
    const cardGroup = buildCard(i, texture, captions[i], CARD_WIDTH, CARD_HEIGHT, BEVEL_WIDTH, ctx);
    cardGroup.position.x = (i - 2) * CARD_PITCH;
    cardGroup.userData.cardIndex = i;
    cardGroup.userData.isFocused = i === 2;

    // Initial non-focused state
    if (i !== 2) {
      cardGroup.scale.set(0.92, 0.92, 0.92);
      // Opacity fades by distance: 1.0 at edge to 0.55 at center
      const distFromFocus = Math.abs(i - 2);
      const opacity = 1.0 - (distFromFocus * 0.225);
      cardGroup.traverse(node => {
        if (node.isMesh) {
          node.material.transparent = true;
          node.material.opacity = opacity;
        }
      });
    }

    cardsArray.push(cardGroup);
    group.add(cardGroup);
  }

  // Rotate entire filmstrip for perspective recession
  group.rotation.y = STRIP_ROTATION_Y;

  // Add static text labels
  const headlineText = ctx.fontAtlas?.createText?.({
    text: 'The collection',
    fontSize: 0.62,
    color: '#16161d',
    anchor: 'left',
  });
  if (headlineText) {
    headlineText.position.set(-2.6, 1.5, 0);
    group.add(headlineText);
  }

  const bodyText = ctx.fontAtlas?.createText?.({
    text: 'Five calibres. One discipline.',
    fontSize: 0.13,
    color: '#16161d',
    anchor: 'left',
  });
  if (bodyText) {
    bodyText.position.set(-2.6, -1.5, 0);
    group.add(bodyText);
  }

  // Apply parallax-scroll cinematic primitive
  if (ctx.primitives?.['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { intensity: 0.5 });
  }

  // Store card references
  group.userData.cards = cardsArray;
  group.userData.focusedCardIndex = 2;

  // Cleanup function
  group.userData.cleanup = () => {
    texture.dispose();
    group.traverse(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        mats.forEach(m => m.dispose());
      }
    });
    gsap.killTweensOf(group);
    cardsArray.forEach(card => {
      gsap.killTweensOf(card);
      gsap.killTweensOf(card.scale);
    });
  };

  return group;
}

function buildCard(index, texture, caption, cardWidth, cardHeight, bevelWidth, ctx) {
  const cardGroup = new THREE.Group();

  // Main card plane with texture
  const cardGeo = new THREE.PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new THREE.MeshStandardMaterial({
    map: texture,
    roughness: 0.55,
    metalness: 0.2,
    clearcoat: 0.15,
    side: THREE.FrontSide,
  });
  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardGroup.add(cardMesh);

  // Machined-metal bevel frame
  const bevelMat = new THREE.MeshStandardMaterial({
    color: '#16161d',
    metalness: 0.6,
    roughness: 0.7,
    side: THREE.FrontSide,
  });

  // Create four bevel edges
  const bevelEdges = [
    { width: cardWidth, height: bevelWidth, x: 0, y: cardHeight / 2 - bevelWidth / 2 }, // top
    { width: cardWidth, height: bevelWidth, x: 0, y: -cardHeight / 2 + bevelWidth / 2 }, // bottom
    { width: bevelWidth, height: cardHeight, x: -cardWidth / 2 + bevelWidth / 2, y: 0 }, // left
    { width: bevelWidth, height: cardHeight, x: cardWidth / 2 - bevelWidth / 2, y: 0 }, // right
  ];

  bevelEdges.forEach(edge => {
    const bevelGeo = new THREE.PlaneGeometry(edge.width, edge.height);
    const bevelMesh = new THREE.Mesh(bevelGeo, bevelMat);
    bevelMesh.position.set(edge.x, edge.y, 0.001);
    cardGroup.add(bevelMesh);
  });

  // Accent underline bar (focused card only)
  const underlineGeo = new THREE.PlaneGeometry(cardWidth, 0.035);
  const underlineMat = new THREE.MeshStandardMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.3,
  });
  const underlineMesh = new THREE.Mesh(underlineGeo, underlineMat);
  underlineMesh.position.set(0, -cardHeight / 2 - 0.05, 0.002);
  underlineMesh.visible = index === 2;
  cardGroup.add(underlineMesh);
  cardGroup.userData.underlineBar = underlineMesh;

  // Card caption text
  if (ctx.fontAtlas?.createText) {
    const captionMesh = ctx.fontAtlas.createText({
      text: caption,
      fontSize: 0.09,
      color: '#16161d',
      anchor: 'center',
    });
    if (captionMesh) {
      captionMesh.position.y = -cardHeight / 2 - 0.2;
      cardGroup.add(captionMesh);
      cardGroup.userData.caption = captionMesh;
    }
  }

  return cardGroup;
}
